<?php require __DIR__.'/includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']!=='POST')go('cart.php');csrf_check();$action=$_POST['action']??'';$id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT);if($action==='clear'){unset($_SESSION['cart']);go('cart.php');}if($action==='remove'&&$id){unset($_SESSION['cart'][$id]);go('cart.php');}if($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=max(0,(int)$qty);if($qty===0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=min(99,$qty);}go('cart.php');}if($action==='add'&&$id){$q=db()->prepare('SELECT stock,is_active FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch();if($p&&$p['is_active']&&(int)$p['stock']>0)$_SESSION['cart'][$id]=min((int)$p['stock'],($_SESSION['cart'][$id]??0)+max(1,(int)($_POST['quantity']??1)));}go('cart.php');